import 'bootstrap/dist/css/bootstrap.min.css';
import Button from 'react-bootstrap/Button';
import { Nav, Navbar, NavDropdown } from "react-bootstrap";
import Logo from "../../Images/Components/Navbar/four.png";
import "./Navbar.css";




function Navbar1(){
 return(
    <Navbar collapseOnSelect expand="lg" bg="" variant="dark">
      <Navbar.Brand href="#home">
        <font id='heading1'><img src={Logo} className='church-logo'/>Foursquare</font>
      </Navbar.Brand>
      <div style={{marginRight:"_300px"}}>
        <Nav id="navlink1" > 
          <Nav.Link href="#" id='navlink' style={{color:'black'}}>HOME</Nav.Link>
          <Nav.Link href="#" id='' style={{color:'black'}}>ABOUT</Nav.Link>
          <Nav.Link href="#" id='' style={{color:'black'}}> SERVE</Nav.Link>
          <Nav.Link href="#" id='' style={{color:'black'}}>MEDIA</Nav.Link>
          <Nav.Link href="#" id='' style={{color:'black'}}>CONTANT US</Nav.Link>
        </Nav>
        </div>
      </Navbar>
);
}
export default Navbar1;
